# embed_glsl.py -- turns a third-party GLSL header into a C++ include of string pieces.
#
#   python embed_glsl.py fsr1/ffx_fsr1.h nis/NIS_Scaler.h
#
# Writes <header minus .h>.glsl.inc next to each header: the header's text, unchanged, as a list of raw string
# literals (an initializer list for a `const char* const[]`), cut at line ends into pieces under MSVC's 16 KB limit
# for one literal. vr_upscale.cpp joins them and hands them to the GL compiler after its own definitions. Run it again
# after updating a header.

import os
import sys

DELIM = "QVRGLSL"
PIECE = 12000

def embed(path):
    with open(path, "r", encoding="ascii", newline="") as f:
        text = f.read().replace("\r\n", "\n")
    if (")" + DELIM + '"') in text:
        raise SystemExit(path + ": contains the raw string delimiter")
    pieces, current = [], ""
    for line in text.splitlines(keepends=True):
        if current and len(current) + len(line) > PIECE:
            pieces.append(current)
            current = ""
        current += line
    if current:
        pieces.append(current)
    out = os.path.splitext(path)[0] + ".glsl.inc"
    name = os.path.basename(path)
    with open(out, "w", encoding="ascii", newline="\n") as f:
        f.write("// Generated by external/embed_glsl.py from %s (its text unchanged, in pieces under MSVC's\n" % name)
        f.write("// 16 KB limit for a string literal). Do not edit: update %s and run the script again.\n" % name)
        for p in pieces:
            f.write('R"%s(%s)%s",\n' % (DELIM, p, DELIM))
    print("%s: %d bytes in %d pieces" % (out, len(text), len(pieces)))

for arg in sys.argv[1:]:
    embed(arg)
